package com.companages.security;
import com.companages.exception.ApiError; import com.fasterxml.jackson.databind.ObjectMapper; import jakarta.servlet.http.*; import org.springframework.http.*; import org.springframework.security.access.AccessDeniedException; import org.springframework.security.core.AuthenticationException; import org.springframework.security.web.AuthenticationEntryPoint; import org.springframework.security.web.access.AccessDeniedHandler; import org.springframework.stereotype.Component; import java.io.IOException; import java.time.Instant; import java.util.Map;
@Component public class RestSecurityHandler implements AuthenticationEntryPoint,AccessDeniedHandler { private final ObjectMapper json; public RestSecurityHandler(ObjectMapper j){json=j;} public void commence(HttpServletRequest q,HttpServletResponse r,AuthenticationException e)throws IOException{write(q,r,HttpStatus.UNAUTHORIZED,"Authentication is required");} public void handle(HttpServletRequest q,HttpServletResponse r,AccessDeniedException e)throws IOException{write(q,r,HttpStatus.FORBIDDEN,"Access is denied");} private void write(HttpServletRequest q,HttpServletResponse r,HttpStatus s,String message)throws IOException{r.setStatus(s.value());r.setContentType(MediaType.APPLICATION_JSON_VALUE);json.writeValue(r.getOutputStream(),new ApiError(Instant.now(),s.value(),s.getReasonPhrase(),message,q.getRequestURI(),Map.of()));} }
